#!/usr/bin/env bash
# Create test users and rooms with some history. Safe to re-run.
set -euo pipefail
source "$(dirname "$0")/lib.sh"

# Tiny PNGs so avatars and image messages have something to show.
PNG_ALICE=""
PNG_BOB=""
PNG_CAROL=""
PNG_GENERAL=""
PNG_PHOTO=""
MP4_TINY=""
THUMB_TINY=""
M4A_TINY=""

echo "users:"
register_user alice alice-password --admin
register_user bob bob-password
register_user carol carol-password

ALICE=$(login alice alice-password)
BOB=$(login bob bob-password)
CAROL=$(login carol carol-password)

# upload <token> <base64-png> -> prints mxc uri
upload() {
  base64 -d <<<"$2" | curl -fsS -X POST "$HS_URL/_matrix/media/v3/upload?filename=image.png" \
    -H "Authorization: Bearer $1" -H 'Content-Type: image/png' --data-binary @- | jq -r .content_uri
}

# set_avatar <token> <user-id> <base64-png>
set_avatar() {
  local mxc; mxc=$(upload "$1" "$3")
  api "$1" PUT "/_matrix/client/v3/profile/$2/avatar_url" "$(jq -nc --arg u "$mxc" '{avatar_url:$u}')" >/dev/null
}

# ensure_room <alias-localpart> <name> <topic> -> prints room id
ensure_room() {
  local alias="$1" name="$2" topic="$3" room_id
  if room_id=$(curl -fsS "$HS_URL/_matrix/client/v3/directory/room/%23$alias:localhost" 2>/dev/null | jq -r .room_id); then
    echo "  = #$alias ($room_id)" >&2
  else
    room_id=$(api "$ALICE" POST /_matrix/client/v3/createRoom "$(jq -nc \
      --arg a "$alias" --arg n "$name" --arg t "$topic" \
      '{room_alias_name:$a, name:$n, topic:$t, preset:"public_chat", invite:["@bob:localhost","@carol:localhost"]}')" | jq -r .room_id)
    api "$BOB" POST "/_matrix/client/v3/join/$room_id" '{}' >/dev/null
    api "$CAROL" POST "/_matrix/client/v3/join/$room_id" '{}' >/dev/null
    echo "  + #$alias ($room_id)" >&2
  fi
  echo "$room_id"
}

# ensure_space <alias-localpart> <name> <topic> -> prints room id
ensure_space() {
  local alias="$1" name="$2" topic="$3" room_id
  if room_id=$(curl -fsS "$HS_URL/_matrix/client/v3/directory/room/%23$alias:localhost" 2>/dev/null | jq -r .room_id); then
    echo "  = #$alias ($room_id)" >&2
  else
    room_id=$(api "$ALICE" POST /_matrix/client/v3/createRoom "$(jq -nc \
      --arg a "$alias" --arg n "$name" --arg t "$topic" \
      '{room_alias_name:$a, name:$n, topic:$t, preset:"public_chat", creation_content:{type:"m.space"}, invite:["@bob:localhost","@carol:localhost"]}')" | jq -r .room_id)
    api "$BOB" POST "/_matrix/client/v3/join/$room_id" '{}' >/dev/null
    api "$CAROL" POST "/_matrix/client/v3/join/$room_id" '{}' >/dev/null
    echo "  + #$alias ($room_id)" >&2
  fi
  echo "$room_id"
}

# add_space_child <token> <space-room-id> <child-room-id>
# Sets m.space.child on the space, pointing at the child room.
add_space_child() {
  api "$1" PUT "/_matrix/client/v3/rooms/$2/state/m.space.child/$3" \
    "$(jq -nc '{via:["localhost"]}')" >/dev/null
}

# add_space_parent <token> <room-id> <space-room-id>
# Sets m.space.parent on the room, pointing at the space. Together with
# add_space_child this makes the relationship reciprocal, as the spec
# recommends: https://spec.matrix.org/latest/client-server-api/#mspaceparent-relationships
add_space_parent() {
  api "$1" PUT "/_matrix/client/v3/rooms/$2/state/m.space.parent/$3" \
    "$(jq -nc '{via:["localhost"], canonical:true}')" >/dev/null
}

# say <token> <room> <text>
say() {
  api "$1" PUT "/_matrix/client/v3/rooms/$2/send/m.room.message/seed-$(date +%s%N)" \
    "$(jq -nc --arg b "$3" '{msgtype:"m.text", body:$b}')" >/dev/null
}

# say_html <token> <room> <plain> <html>
say_html() {
  api "$1" PUT "/_matrix/client/v3/rooms/$2/send/m.room.message/seed-$(date +%s%N)" \
    "$(jq -nc --arg b "$3" --arg h "$4" '{msgtype:"m.text", body:$b, format:"org.matrix.custom.html", formatted_body:$h}')" >/dev/null
}

# send_image <token> <room> <base64-png> <caption>
send_image() {
  local mxc; mxc=$(upload "$1" "$3")
  api "$1" PUT "/_matrix/client/v3/rooms/$2/send/m.room.message/seed-$(date +%s%N)" \
    "$(jq -nc --arg u "$mxc" --arg b "$4" '{msgtype:"m.image", body:$b, url:$u, info:{mimetype:"image/png", w:320, h:200}}')" >/dev/null
}

# upload_typed <token> <base64> <mimetype> <filename> -> prints mxc uri
upload_typed() {
  base64 -d <<<"$2" | curl -fsS -X POST "$HS_URL/_matrix/media/v3/upload?filename=$4" \
    -H "Authorization: Bearer $1" -H "Content-Type: $3" --data-binary @- | jq -r .content_uri
}

# send_file <token> <room> <base64> <filename> <mimetype> <caption>
send_file() {
  local mxc size
  mxc=$(upload_typed "$1" "$3" "$5" "$4")
  size=$(base64 -d <<<"$3" | wc -c)
  api "$1" PUT "/_matrix/client/v3/rooms/$2/send/m.room.message/seed-$(date +%s%N)" \
    "$(jq -nc --arg u "$mxc" --arg b "$6" --arg f "$4" --arg m "$5" --argjson s "$size" \
      '{msgtype:"m.file", body:$b, filename:$f, url:$u, info:{mimetype:$m, size:$s}}')" >/dev/null
}

# send_video <token> <room> <base64-mp4> <filename> <base64-thumb-png> <width> <height> <duration-ms> <caption>
send_video() {
  local mxc thumb_mxc size
  mxc=$(upload_typed "$1" "$3" "video/mp4" "$4")
  thumb_mxc=$(upload "$1" "$5")
  size=$(base64 -d <<<"$3" | wc -c)
  api "$1" PUT "/_matrix/client/v3/rooms/$2/send/m.room.message/seed-$(date +%s%N)" \
    "$(jq -nc --arg u "$mxc" --arg b "$9" --arg f "$4" --arg tu "$thumb_mxc" \
      --argjson w "$6" --argjson h "$7" --argjson d "$8" --argjson s "$size" \
      '{msgtype:"m.video", body:$b, filename:$f, url:$u,
        info:{mimetype:"video/mp4", w:$w, h:$h, duration:$d, size:$s,
              thumbnail_url:$tu, thumbnail_info:{mimetype:"image/png", w:$w, h:$h}}}')" >/dev/null
}

# send_audio <token> <room> <base64-m4a> <filename> <duration-ms> <caption>
send_audio() {
  local mxc size
  mxc=$(upload_typed "$1" "$3" "audio/mp4" "$4")
  size=$(base64 -d <<<"$3" | wc -c)
  api "$1" PUT "/_matrix/client/v3/rooms/$2/send/m.room.message/seed-$(date +%s%N)" \
    "$(jq -nc --arg u "$mxc" --arg b "$6" --arg f "$4" --argjson d "$5" --argjson s "$size" \
      '{msgtype:"m.audio", body:$b, filename:$f, url:$u, info:{mimetype:"audio/mp4", duration:$d, size:$s}}')" >/dev/null
}

# react <token> <room> <event-id> <key>
react() {
  api "$1" PUT "/_matrix/client/v3/rooms/$2/send/m.reaction/seed-$(date +%s%N)" \
    "$(jq -nc --arg e "$3" --arg k "$4" '{"m.relates_to":{rel_type:"m.annotation", event_id:$e, key:$k}}')" >/dev/null
}

# say_get_id <token> <room> <text> -> prints event id
say_get_id() {
  api "$1" PUT "/_matrix/client/v3/rooms/$2/send/m.room.message/seed-$(date +%s%N)" \
    "$(jq -nc --arg b "$3" '{msgtype:"m.text", body:$b}')" | jq -r .event_id
}

# thread_reply <token> <room> <root-event-id> <fallback-event-id> <text> -> prints event id
thread_reply() {
  api "$1" PUT "/_matrix/client/v3/rooms/$2/send/m.room.message/seed-$(date +%s%N)" \
    "$(jq -nc --arg b "$5" --arg root "$3" --arg fallback "$4" \
      '{msgtype:"m.text", body:$b, "m.relates_to":{rel_type:"m.thread", event_id:$root, is_falling_back:true, "m.in_reply_to":{event_id:$fallback}}}')" \
    | jq -r .event_id
}

echo "rooms:"
GENERAL=$(ensure_room general "general" "Where everything starts")
RANDOM_ROOM=$(ensure_room random "random" "Off-topic")
DEV=$(ensure_room dev "dev" "Building Morpheus")

# Calls: members post their call membership as state, which needs power
# level 0 for it (rooms Morpheus creates set this; older rooms get it here).
allow_calls() {
  local pl
  pl=$(api "$ALICE" GET "/_matrix/client/v3/rooms/$1/state/m.room.power_levels/")
  if [[ $(jq -r '.events["org.matrix.msc3401.call.member"] // "unset"' <<<"$pl") != "0" ]]; then
    api "$ALICE" PUT "/_matrix/client/v3/rooms/$1/state/m.room.power_levels/" \
      "$(jq -c '.events["org.matrix.msc3401.call.member"] = 0' <<<"$pl")" >/dev/null
    echo "  + calls allowed in $1" >&2
  fi
}
ENC=$(curl -fsS "$HS_URL/_matrix/client/v3/directory/room/%23encrypted:localhost" 2>/dev/null | jq -r .room_id) || ENC=""
# (#encrypted too, for now: its leftovers can only be hung up while allowed.)
for room in "$GENERAL" "$RANDOM_ROOM" "$DEV" $ENC; do allow_calls "$room"; done

# Test runs that died mid-call leave memberships behind; hang them up.
clear_calls() {
  local key token
  for key in $(api "$ALICE" GET "/_matrix/client/v3/rooms/$1/state" \
      | jq -r '.[] | select(.type=="org.matrix.msc3401.call.member" and .content.device_id != null) | .state_key'); do
    case "$key" in
      *@alice:*) token=$ALICE ;; *@bob:*) token=$BOB ;; *@carol:*) token=$CAROL ;; *) continue ;;
    esac
    api "$token" PUT "/_matrix/client/v3/rooms/$1/state/org.matrix.msc3401.call.member/$(jq -rn --arg k "$key" '$k|@uri')" '{}' >/dev/null
    echo "  - hung up $key" >&2
  done
}
for room in "$GENERAL" "$RANDOM_ROOM" "$DEV" $ENC; do clear_calls "$room"; done
# #encrypted starts each run without calls allowed: the calls e2e test has
# its admin turn them on by joining.
if [[ -n "$ENC" ]]; then
  pl=$(api "$ALICE" GET "/_matrix/client/v3/rooms/$ENC/state/m.room.power_levels/")
  if [[ $(jq -r '.events["org.matrix.msc3401.call.member"] // "unset"' <<<"$pl") != "unset" ]]; then
    api "$ALICE" PUT "/_matrix/client/v3/rooms/$ENC/state/m.room.power_levels/" \
      "$(jq -c 'del(.events["org.matrix.msc3401.call.member"])' <<<"$pl")" >/dev/null
  fi
fi

echo "spaces:"
ENGINEERING=$(ensure_space engineering "Engineering" "Everything about building Morpheus")
add_space_child "$ALICE" "$ENGINEERING" "$DEV"
add_space_parent "$ALICE" "$DEV" "$ENGINEERING"
echo "  + #dev is a child of #engineering (space); #general and #random stay outside it"

if [[ ! -f "$HS_DIR/.seeded" ]]; then
  echo "profiles:"
  set_avatar "$ALICE" "@alice:localhost" "$PNG_ALICE"
  set_avatar "$BOB" "@bob:localhost" "$PNG_BOB"
  set_avatar "$CAROL" "@carol:localhost" "$PNG_CAROL"
  GENERAL_AVATAR=$(upload "$ALICE" "$PNG_GENERAL")
  api "$ALICE" PUT "/_matrix/client/v3/rooms/$GENERAL/state/m.room.avatar" "$(jq -nc --arg u "$GENERAL_AVATAR" '{url:$u}')" >/dev/null
  echo "  + avatars"

  echo "messages:"
  say "$ALICE" "$GENERAL" "Welcome to Morpheus"
  say "$BOB"   "$GENERAL" "hey! is this the new client?"
  say "$ALICE" "$GENERAL" "yep, Rust + Dioxus on top of matrix-rust-sdk"
  say "$ALICE" "$GENERAL" "this message should group under the one above"
  say_html "$CAROL" "$GENERAL" "looks **fast** 👀 — check https://matrix.org" \
    'looks <strong>fast</strong> 👀 — check <a href="https://matrix.org">matrix.org</a>'
  send_image "$BOB" "$GENERAL" "$PNG_PHOTO" "morpheus.png"
  say_html "$ALICE" "$GENERAL" "code:\n\`\`\`rust\nfn main() {}\n\`\`\`" \
    'code:<pre><code class="language-rust">fn main() {}</code></pre>'
  LAST=$(api "$CAROL" PUT "/_matrix/client/v3/rooms/$GENERAL/send/m.room.message/seed-$(date +%s%N)" \
    "$(jq -nc '{msgtype:"m.text", body:"react to this one"}')" | jq -r .event_id)
  react "$ALICE" "$GENERAL" "$LAST" "👍"
  react "$BOB" "$GENERAL" "$LAST" "👍"
  react "$BOB" "$GENERAL" "$LAST" "🎉"

  echo "thread:"
  THREAD_ROOT=$(say_get_id "$ALICE" "$GENERAL" "Let's plan Q4 in this thread")
  THREAD_REPLY_1=$(thread_reply "$BOB" "$GENERAL" "$THREAD_ROOT" "$THREAD_ROOT" "I think threads should ship first")
  thread_reply "$CAROL" "$GENERAL" "$THREAD_ROOT" "$THREAD_REPLY_1" "Agreed, then the emoji picker" >/dev/null
  echo "  + thread seeded"

  for i in $(seq 1 80); do say "$BOB" "$RANDOM_ROOM" "random filler message $i"; done
  say "$CAROL" "$DEV" "sliding sync is working if you can read this"
  say "$ALICE" "$DEV" "next: avatars and media"
  send_file "$BOB" "$DEV" "$(base64 -w0 <<<"Morpheus release notes.
- File, audio and video attachments now download and play.
- Downloads land in your Downloads folder, suffixed if a name collides.")" \
    "release-notes.txt" "text/plain" "release-notes.txt"
  send_video "$ALICE" "$DEV" "$MP4_TINY" "clip.mp4" "$THUMB_TINY" 160 120 1000 "clip.mp4"
  send_audio "$CAROL" "$DEV" "$M4A_TINY" "voice-note.m4a" 1000 "voice-note.m4a"
  touch "$HS_DIR/.seeded"
  echo "  + seeded"
else
  echo "messages: already seeded (delete dev/homeserver/.seeded to re-seed)"
fi

# A direct message between alice and bob, flagged on both sides via m.direct
# so clients treat it as a DM (Synapse's is_direct only marks the invite).
if [[ ! -f "$HS_DIR/.seeded-dm" ]]; then
  echo "dm:"
  DM=$(api "$ALICE" POST /_matrix/client/v3/createRoom \
    '{"is_direct":true, "preset":"trusted_private_chat", "invite":["@bob:localhost"]}' | jq -r .room_id)
  api "$BOB" POST "/_matrix/client/v3/join/$DM" '{}' >/dev/null
  api "$ALICE" PUT "/_matrix/client/v3/user/@alice:localhost/account_data/m.direct" \
    "$(jq -nc --arg r "$DM" '{"@bob:localhost":[$r]}')" >/dev/null
  api "$BOB" PUT "/_matrix/client/v3/user/@bob:localhost/account_data/m.direct" \
    "$(jq -nc --arg r "$DM" '{"@alice:localhost":[$r]}')" >/dev/null
  say "$BOB" "$DM" "hey alice, this is our dm"
  say "$ALICE" "$DM" "hi bob"
  touch "$HS_DIR/.seeded-dm"
  echo "  + alice <-> bob ($DM)"
fi

# An encrypted room holding one event no device can decrypt (the ciphertext
# is made up), so the "waiting for keys" rendering has something to show.
if [[ ! -f "$HS_DIR/.seeded-encrypted" ]]; then
  echo "encrypted:"
  ENCRYPTED=$(ensure_room encrypted "encrypted" "Megolm without the keys")
  api "$ALICE" PUT "/_matrix/client/v3/rooms/$ENCRYPTED/state/m.room.encryption" \
    '{"algorithm":"m.megolm.v1.aes-sha2"}' >/dev/null
  api "$BOB" PUT "/_matrix/client/v3/rooms/$ENCRYPTED/send/m.room.encrypted/seed-utd-$(date +%s%N)" \
    '{"algorithm":"m.megolm.v1.aes-sha2","ciphertext":"AwgAEnACgAkAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA","device_id":"SEEDDEVICE","sender_key":"c2VlZC1zZW5kZXIta2V5LXRoYXQtaXMtbm90LXJlYWwAAAAAAAA","session_id":"c2VlZC1zZXNzaW9uLWlkLW5vdC1yZWFsAAAAAAAAAAAAAAAAAAA"}' >/dev/null
  touch "$HS_DIR/.seeded-encrypted"
  echo "  + #encrypted with one undecryptable event"
fi

# A room with 150 extra members (admin API, no logins) so the member list's
# windowing has something to window.
if [[ ! -f "$HS_DIR/.seeded-crowd" ]]; then
  echo "crowd:"
  CROWD=$(ensure_room crowd "crowd" "150 members for the member list")
  for i in $(seq -w 1 150); do
    api "$ALICE" PUT "/_synapse/admin/v2/users/@crowd$i:localhost" \
      "$(jq -nc --arg d "Crowd $i" '{password:"crowd-password", displayname:$d}')" >/dev/null
    api "$ALICE" POST "/_synapse/admin/v1/join/$CROWD" "$(jq -nc --arg u "@crowd$i:localhost" '{user_id:$u}')" >/dev/null
  done
  touch "$HS_DIR/.seeded-crowd"
  echo "  + 150 members joined #crowd"
fi

# A room for moderation tests. Restored on every run: tests kick and ban
# bob and carol here, so unban them and join them back each time.
echo "moderation:"
MODERATION=$(ensure_room moderation "moderation" "Kick and ban live here")
for u in bob carol; do
  api "$ALICE" POST "/_matrix/client/v3/rooms/$MODERATION/unban" "$(jq -nc --arg u "@$u:localhost" '{user_id:$u}')" >/dev/null 2>&1 || true
  api "$ALICE" POST "/_synapse/admin/v1/join/$MODERATION" "$(jq -nc --arg u "@$u:localhost" '{user_id:$u}')" >/dev/null
done
echo "  = bob and carol are members again"

# Garbage-collect rooms the tests create (servers, categories, rooms made
# through the UI or the core live tests). Keeps the server small and fast.
echo "gc:"
GC_COUNT=0
while read -r room_id name; do
  case "$name" in
    "srv "*|"live srv"*|"live category"|"live chatter"|"live invite"*|"Text channels"|"chatter"|"curl "*|"e2e room"*|"space room"*)
      # A purge leaves pending invites behind; decline them first.
      for tok in "$BOB" "$CAROL"; do api "$tok" POST "/_matrix/client/v3/rooms/$room_id/leave" '{}' >/dev/null 2>&1 || true; done
      api "$ALICE" DELETE "/_synapse/admin/v1/rooms/$room_id" '{"purge": true}' >/dev/null 2>&1 || true
      GC_COUNT=$((GC_COUNT + 1));;
  esac
done < <(api "$ALICE" GET "/_synapse/admin/v1/rooms?limit=500" | jq -r '.rooms[] | "\(.room_id) \(.name // "")"')
echo "  - removed $GC_COUNT leftover test rooms"

# Tests rename users and set statuses; a run that dies midway leaves them
# changed, and later tests match on the seeded names. Put them back each run.
echo "names:"
for pair in "alice:$ALICE" "bob:$BOB" "carol:$CAROL"; do
  u="${pair%%:*}"; tok="${pair#*:}"
  api "$tok" PUT "/_matrix/client/v3/profile/@$u:localhost/displayname" "$(jq -nc --arg n "$u" '{displayname:$n}')" >/dev/null
  api "$tok" PUT "/_matrix/client/v3/presence/@$u:localhost/status" '{"presence":"online"}' >/dev/null 2>&1 || true
done
echo "  = display names reset to alice, bob, carol"

# Rooms purged by an earlier run leave their invites dangling; decline them all.
for pair in "alice:$ALICE" "bob:$BOB" "carol:$CAROL"; do
  u="${pair%%:*}"; tok="${pair#*:}"
  for room_id in $(api "$tok" GET "/_matrix/client/v3/sync?timeout=0&filter=%7B%22room%22%3A%7B%22timeline%22%3A%7B%22limit%22%3A0%7D%7D%7D" | jq -r '.rooms.invite // {} | keys[]'); do
    api "$tok" POST "/_matrix/client/v3/rooms/$room_id/leave" '{}' >/dev/null 2>&1 || true
  done
done
echo "  = pending invites declined"

if [[ ! -f "$HS_DIR/.seeded-firehose" ]]; then
  echo "firehose:"
  FIREHOSE=$(ensure_room firehose "firehose" "600 messages for performance tests")
  for i in $(seq 1 600); do say "$BOB" "$FIREHOSE" "firehose message $i"; done
  touch "$HS_DIR/.seeded-firehose"
  echo "  + 600 messages"
fi

# Every test login leaves a device behind (alice had 1300+), and each one
# adds key queries to every sync and fans out verification requests. Last
# step, since it also signs out the tokens this script used.
# alice last: her token is the admin one doing the deleting.
for u in bob carol alice; do
  ids=$(api "$ALICE" GET "/_synapse/admin/v2/users/@$u:localhost/devices" | jq -c "[.devices[].device_id]")
  api "$ALICE" POST "/_synapse/admin/v2/users/@$u:localhost/delete_devices" "$(jq -nc --argjson d "$ids" '{devices:$d}')" >/dev/null
done
echo "  = old devices removed"

cat <<INFO

ready. log in with:
  homeserver  $HS_URL
  alice / alice-password   (admin)
  bob   / bob-password
  carol / carol-password
INFO
